class DepotAvecCache(IDepot inner) : IDepot
{
    readonly Dictionary<int, Produit> _cache = new();
    public Produit Lire(int id)
    {
        if (!_cache.TryGetValue(id, out var p))
            _cache[id] = p = inner.Lire(id);
        return p;
    }
}

